<?php require_once __DIR__.'/../config/db.php';require_once __DIR__.'/../includes/functions.php';if(empty($_SESSION['admin_id'])){header('Location: login.php');exit;}$pageTitle='Add product';$error='';$success='';$cats=$pdo->query('SELECT id,name FROM categories ORDER BY name')->fetchAll();if($_SERVER['REQUEST_METHOD']==='POST'){check_token();$name=trim((string)($_POST['name']??''));$desc=trim((string)($_POST['description']??''));$cat=(int)($_POST['category_id']??0);$price=filter_var($_POST['price']??null,FILTER_VALIDATE_FLOAT);$stock=filter_var($_POST['stock']??null,FILTER_VALIDATE_INT);if($name===''||$desc===''||$price===false||$price<=0||$stock===false||$stock<0)$error='Check all fields and use a positive price and non-negative stock.';else{$s=$pdo->prepare('INSERT INTO products(category_id,name,description,base_price,stock_quantity) VALUES(?,?,?,?,?)');$s->execute([$cat,$name,$desc,$price,$stock]);$success='Product added.';}}require __DIR__.'/../includes/header.php'; ?><div class="container section-space" style="max-width:700px"><h1 class="h2 mb-4">Add product</h1><div class="panel"><?php if($error): ?><div class="alert alert-danger"><?=e($error)?></div><?php endif; ?><?php if($success): ?><div class="alert alert-success"><?=e($success)?></div><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?=e(token())?>"><label class="form-label">Name</label><input class="form-control mb-3" name="name" maxlength="160" required><label class="form-label">Description</label><textarea class="form-control mb-3" name="description" required></textarea><label class="form-label">Category</label><select class="form-select mb-3" name="category_id" required><?php foreach($cats as $c): ?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach; ?></select><div class="row"><div class="col"><label class="form-label">Price</label><input class="form-control mb-3" type="number" step=".01" min=".01" name="price" required></div><div class="col"><label class="form-label">Stock</label><input class="form-control mb-3" type="number" min="0" name="stock" value="0" required></div></div><button class="btn btn-dark rounded-pill">Save product</button></form></div></div><?php require __DIR__.'/../includes/footer.php'; ?>